<script lang="ts">import {phasesFor} from '../lib/roadmapMilestoneRegistry.ts';export let open=false;export let onClose:()=>void=()=>{};export let onCreate:(request:any)=>void=()=>{};let title='',description='',origin:'ROADMAP'|'NEW'='NEW',milestone='',phase='',selected_template='',repository='',priority='NORMAL';$: phases=phasesFor(milestone);function submit(){onCreate({title,description,origin,milestone:milestone||null,phase:phase||null,selected_template:selected_template||null,execution_type:'IMPLEMENTATION',priority,repository,branch_policy:'DETERMINISTIC_DELIVERY'});title='';description='';}</script>
{#if open}<div class="modal-backdrop" role="presentation"><form class="create-wp-modal" data-testid="create-wp-modal" onsubmit={(event)=>{event.preventDefault();submit()}}><h3>创建 Work Package</h3><label>Title<input bind:value={title} required /></label><label>Description<textarea bind:value={description}></textarea></label><fieldset><legend>Origin</legend><label><input type="radio" bind:group={origin} value="ROADMAP" /> Roadmap WP</label><label><input type="radio" bind:group={origin} value="NEW" /> New WP</label></fieldset><label>Milestone<select bind:value={milestone}><option value="">Select milestone</option><option>M7</option><option>M8</option><option>M9</option><option>M10</option></select></label><label>Phase<select bind:value={phase}><option value="">Select phase</option>{#each phases as phaseOption}<option value={phaseOption}>{phaseOption}</option>{/each}</select></label><label>Roadmap Template<select bind:value={selected_template}><option value="">Default template</option><option value={phase}>{phase||'Selected phase template'}</option></select></label><label>Repository<input bind:value={repository} /></label><label>Priority<select bind:value={priority}><option>HIGH</option><option>NORMAL</option><option>LOW</option></select></label><div><button type="button" onclick={onClose}>取消</button><button type="submit">创建</button></div></form></div>{/if}
<style>.modal-backdrop{position:fixed;inset:0;z-index:20;display:grid;place-items:center;background:#0005}.create-wp-modal{display:grid;gap:10px;width:min(480px,90vw);padding:18px;border:1px solid var(--border);border-radius:10px;background:var(--surface)}.create-wp-modal label{display:grid;gap:4px;font-size:12px}.create-wp-modal input,.create-wp-modal textarea,.create-wp-modal select{padding:7px;border:1px solid var(--border);border-radius:6px;background:var(--surface-2);color:var(--text-1)}fieldset{display:flex;gap:12px;border:0;padding:0}fieldset label{display:flex}</style>
